DROP TABLE IF EXISTS `candidatos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `candidatos` (
  `id_candidato` bigint NOT NULL AUTO_INCREMENT,
  `id_partido` bigint NOT NULL,
  `nombres` varchar(120) COLLATE utf8mb4_spanish_ci NOT NULL,
  `apellidos` varchar(120) COLLATE utf8mb4_spanish_ci NOT NULL,
  `cargo` varchar(80) COLLATE utf8mb4_spanish_ci NOT NULL,
  `integrantes` text COLLATE utf8mb4_spanish_ci,
  `imagen` mediumblob,
  `orden_lista` int NOT NULL DEFAULT '1',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_candidato`),
  KEY `idx_candidato_partido` (`id_partido`),
  CONSTRAINT `fk_candidato_partido` FOREIGN KEY (`id_partido`) REFERENCES `partidos` (`id_partido`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
